"use client";

import { useState } from "react";

const input="mt-1.5 h-11 w-full rounded-lg border border-[#cededb] bg-white px-3 text-sm outline-none focus:border-[#c94848] focus:ring-3 focus:ring-[#c94848]/10";
const blank={name:"",totalCoins:"500",shareCount:5,delaySeconds:5,sortOrder:100,active:true};

export default function RedEnvelopeManager({initialConfiguration}){
  const [config,setConfig]=useState(initialConfiguration);const [draft,setDraft]=useState(null);const [settings,setSettings]=useState(initialConfiguration.settings);const [saving,setSaving]=useState(false);const [message,setMessage]=useState("");const [error,setError]=useState("");
  async function request(method,body,url="/api/admin/red-envelopes"){setSaving(true);setError("");setMessage("");try{const response=await fetch(url,{method,headers:{"Content-Type":"application/json"},...(body?{body:JSON.stringify(body)}:{})});const result=await response.json();if(!response.ok)throw new Error(result.error?.message||"Unable to save settings.");setConfig(result.data);setSettings(result.data.settings);setDraft(null);setMessage("Red Envelope configuration saved.");}catch(e){setError(e.message)}finally{setSaving(false)}}
  return <div className="space-y-6">{(message||error)&&<p className={`rounded-xl px-4 py-3 text-xs font-semibold ${error?"bg-rose-50 text-rose-700":"bg-emerald-50 text-emerald-700"}`}>{error||message}</p>}
    <section className="rounded-2xl border border-[#eadfdd] bg-white p-6"><div className="flex items-start justify-between gap-4"><div><h3 className="font-bold">Global controls</h3><p className="mt-1 text-xs text-[#71847f]">These limits are enforced by the backend, not trusted from Android.</p></div><label className="flex items-center gap-2 rounded-full bg-[#fff1ef] px-4 py-2 text-xs font-bold text-[#a73737]"><input type="checkbox" checked={settings.enabled} onChange={e=>setSettings({...settings,enabled:e.target.checked})}/> Feature enabled</label></div><div className="mt-5 grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><Field label="Maximum pool (coins)"><input className={input} type="number" min="1" value={settings.maxCoins} onChange={e=>setSettings({...settings,maxCoins:e.target.value})}/></Field><Field label="Maximum recipients"><input className={input} type="number" min="1" value={settings.maxShareCount} onChange={e=>setSettings({...settings,maxShareCount:e.target.value})}/></Field><Field label="Maximum countdown (seconds)"><input className={input} type="number" min="0" value={settings.maxDelaySeconds} onChange={e=>setSettings({...settings,maxDelaySeconds:e.target.value})}/></Field><Field label="Claim window (seconds)"><input className={input} type="number" min="10" value={settings.claimWindowSeconds} onChange={e=>setSettings({...settings,claimWindowSeconds:e.target.value})}/></Field></div><div className="mt-5 flex justify-end"><button disabled={saving} onClick={()=>request("PATCH",{entity:"settings",...settings})} className="rounded-lg bg-[#a73737] px-5 py-2.5 text-xs font-bold text-white disabled:opacity-50">Save global controls</button></div></section>
    <section className="overflow-hidden rounded-2xl border border-[#eadfdd] bg-white"><div className="flex items-center justify-between border-b p-5"><div><h3 className="font-bold">Mobile preset tiers</h3><p className="mt-1 text-xs text-[#71847f]">Only active presets are returned to Android, in sort order.</p></div><button onClick={()=>setDraft({...blank})} className="rounded-lg bg-[#c94848] px-4 py-2.5 text-xs font-bold text-white">+ Add preset</button></div><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left text-xs"><thead className="bg-[#fff8f7] text-[#806b67]"><tr><th className="px-5 py-3">Preset</th><th className="px-5 py-3">Pool</th><th className="px-5 py-3">Recipients</th><th className="px-5 py-3">Countdown</th><th className="px-5 py-3">Order</th><th className="px-5 py-3">Status</th></tr></thead><tbody>{config.presets.map(item=><tr key={item.id} onClick={()=>setDraft({...item})} className="cursor-pointer border-t hover:bg-[#fff9f8]"><td className="px-5 py-4 font-bold">{item.name}<span className="mt-1 block font-mono text-[9px] font-normal text-[#968580]">{item.id}</span></td><td className="px-5 py-4 font-semibold">{Number(item.totalCoins).toLocaleString()} coins</td><td className="px-5 py-4">{item.shareCount}</td><td className="px-5 py-4">{item.delaySeconds}s</td><td className="px-5 py-4">{item.sortOrder}</td><td className="px-5 py-4"><span className={`rounded-full px-2.5 py-1 text-[9px] font-bold ${item.active?"bg-emerald-50 text-emerald-700":"bg-slate-100 text-slate-600"}`}>{item.active?"Active":"Hidden"}</span></td></tr>)}</tbody></table>{!config.presets.length&&<p className="p-10 text-center text-sm text-[#71847f]">No presets configured.</p>}</div></section>
    {draft&&<PresetModal draft={draft} saving={saving} onClose={()=>setDraft(null)} onSave={value=>request(value.id?"PATCH":"POST",value)} onDelete={draft.id?()=>request("DELETE",null,`/api/admin/red-envelopes?id=${encodeURIComponent(draft.id)}`):null}/>}</div>
}
function PresetModal({draft,saving,onClose,onSave,onDelete}){const [form,setForm]=useState(draft);const set=(k,v)=>setForm({...form,[k]:v});return <div className="fixed inset-0 z-50 overflow-y-auto bg-[#27100e]/65 p-4"><div className="mx-auto my-8 max-w-xl rounded-2xl bg-white shadow-2xl"><div className="flex items-center justify-between border-b px-6 py-5"><h3 className="text-lg font-bold">{draft.id?"Edit preset":"Create preset"}</h3><button onClick={onClose} className="text-2xl text-[#71847f]">×</button></div><form onSubmit={e=>{e.preventDefault();onSave(form)}} className="space-y-4 p-6"><Field label="Preset name"><input className={input} value={form.name} onChange={e=>set("name",e.target.value)} required maxLength={60}/></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Total pool (coins)"><input className={input} type="number" min="1" value={form.totalCoins} onChange={e=>set("totalCoins",e.target.value)} required/></Field><Field label="Recipient count"><input className={input} type="number" min="1" value={form.shareCount} onChange={e=>set("shareCount",e.target.value)} required/></Field><Field label="Countdown (seconds)"><input className={input} type="number" min="0" value={form.delaySeconds} onChange={e=>set("delaySeconds",e.target.value)} required/></Field><Field label="Sort order"><input className={input} type="number" min="0" value={form.sortOrder} onChange={e=>set("sortOrder",e.target.value)} required/></Field></div><label className="flex items-center gap-3 rounded-lg border p-3 text-xs font-bold"><input type="checkbox" checked={form.active} onChange={e=>set("active",e.target.checked)}/> Available in Android</label><div className="flex justify-between border-t pt-5">{onDelete?<button type="button" disabled={saving} onClick={()=>confirm("Delete this preset?")&&onDelete()} className="text-xs font-bold text-rose-600">Delete preset</button>:<span/>}<div className="flex gap-2"><button type="button" onClick={onClose} className="rounded-lg border px-4 py-2.5 text-xs font-bold">Cancel</button><button disabled={saving} className="rounded-lg bg-[#a73737] px-5 py-2.5 text-xs font-bold text-white disabled:opacity-50">{saving?"Saving…":"Save"}</button></div></div></form></div></div>}
function Field({label,children}){return <label className="block text-xs font-bold">{label}{children}</label>}
